{"filePath": "f:\Enkript\lib\services\encryption_service.dart", "content": "import 'dart:convert';
import 'dart:typed_data';
import 'package:encrypt/encrypt.dart';
import 'package:crypto/crypto.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

class EncryptionService {
  static final EncryptionService _instance = EncryptionService._internal();
  factory EncryptionService() => _instance;
  EncryptionService._internal();

  static EncryptionService get instance => _instance;

  final FlutterSecureStorage _secureStorage = const FlutterSecureStorage(
    aOptions: AndroidOptions(
      encryptedSharedPreferences: true,
    ),
  );

  late Encrypter _encrypter;
  late IV _iv;
  bool _isInitialized = false;

  Future<void> initialize() async {
    if (_isInitialized) return;

    // Get or create encryption key
    String? keyString = await _secureStorage.read(key: 'encryption_key');

    if (keyString == null) {
      // Generate new key
      final key = Key.fromSecureRandom(32);
      keyString = base64Encode(key.bytes);
      await _secureStorage.write(key: 'encryption_key', value: keyString);
    }

    // Get or create IV
    String? ivString = await _secureStorage.read(key: 'encryption_iv');

    if (ivString == null) {
      // Generate new IV
      final iv = IV.fromSecureRandom(16);
      ivString = base64Encode(iv.bytes);
      await _secureStorage.write(key: 'encryption_iv', value: ivString);
    }

    final key = Key(base64Decode(keyString));
    _iv = IV(base64Decode(ivString));
    _encrypter = Encrypter(AES(key, mode: AESMode.cbc));
    _isInitialized = true;
  }

  /// Encrypt a string
  String encrypt(String plainText) {
    if (!_isInitialized) {
      throw StateError('EncryptionService not initialized');
    }
    return _encrypter.encrypt(plainText, iv: _iv).base64;
  }

  /// Decrypt a string
  String decrypt(String encryptedText) {
    if (!_isInitialized) {
      throw StateError('EncryptionService not initialized');
    }
    return _encrypter.decrypt64(encryptedText, iv: _iv);
  }

  /// Hash a string (for master password verification)
  String hash(String text) {
    final bytes = utf8.encode(text);
    final digest = sha256.convert(bytes);
    return digest.toString();
  }

  /// Generate a secure key from password using PBKDF2
  Future<String> deriveKeyFromPassword(String password, String salt) async {
    // Simple implementation - in production, use proper PBKDF2
    final combined = password + salt;
    final bytes = utf8.encode(combined);
    final digest = sha256.convert(bytes);
    return base64Encode(digest.bytes);
  }

  /// Clear all encryption keys (for logout)
  Future<void> clearKeys() async {
    await _secureStorage.deleteAll();
    _isInitialized = false;
  }

  /// Store master password hash
  Future<void> storeMasterPasswordHash(String password) async {
    final hashedPassword = hash(password);
    await _secureStorage.write(key: 'master_password_hash', value: hashedPassword);
  }

  /// Verify master password
  Future<bool> verifyMasterPassword(String password) async {
    final storedHash = await _secureStorage.read(key: 'master_password_hash');
    if (storedHash == null) return false;
    return storedHash == hash(password);
  }

  /// Check if master password is set
  Future<bool> isMasterPasswordSet() async {
    final hash = await _secureStorage.read(key: 'master_password_hash');
    return hash != null;
  }
}
"}

{"filePath": "f:\Enkript\lib\services\biometric_service.dart", "content": "import 'package:local_auth/local_auth.dart';
import 'package:flutter/services.dart';

class BiometricService {
  static final BiometricService _instance = BiometricService._internal();
  factory BiometricService() => _instance;
  BiometricService._internal();

  static BiometricService get instance => _instance;

  final LocalAuthentication _localAuth = LocalAuthentication();
  bool _isAvailable = false;
  List<BiometricType> _availableBiometrics = [];

  Future<void> initialize() async {
    try {
      _isAvailable = await _localAuth.canCheckBiometrics;
      if (_isAvailable) {
        _availableBiometrics = await _localAuth.getAvailableBiometrics();
      }
    } catch (e) {
      _isAvailable = false;
      _availableBiometrics = [];
    }
  }

  /// Check if biometric authentication is available
  bool get isAvailable => _isAvailable;

  /// Get available biometric types
  List<BiometricType> get availableBiometrics => _availableBiometrics;

  /// Check if device has fingerprint sensor
  bool get hasFingerprint => _availableBiometrics.contains(BiometricType.fingerprint);

  /// Check if device has face recognition
  bool get hasFaceRecognition => _availableBiometrics.contains(BiometricType.face);

  /// Authenticate user with biometrics
  Future<bool> authenticate({
    String localizedReason = 'Please authenticate to access your passwords',
    bool useErrorDialogs = true,
    bool stickyAuth = true,
  }) async {
    if (!_isAvailable) {
      return false;
    }

    try {
      return await _localAuth.authenticate(
        localizedReason: localizedReason,
        options: AuthenticationOptions(
          useErrorDialogs: useErrorDialogs,
          stickyAuth: stickyAuth,
          biometricOnly: false,
        ),
      );
    } on PlatformException catch (e) {
      print('Biometric authentication error: ${e.message}');
      return false;
    }
  }

  /// Get biometric type name for display
  String getBiometricTypeName() {
    if (hasFaceRecognition) return 'Face Recognition';
    if (hasFingerprint) return 'Fingerprint';
    return 'Biometric';
  }

  /// Stop authentication (if in progress)
  Future<void> stopAuthentication() async {
    try {
      await _localAuth.stopAuthentication();
    } catch (e) {
      // Ignore errors during stop
    }
  }
}
"}

